            keyPhrases: [{ en: "in the 70s", zh: "七十多度（华氏，约21-26°C）" }, { en: "below 32", zh: "32度以下（结冰点）" }],
            culturalNote: "'In the 70s' 表示70-79度之间。美国人谈天气经常用这种范围说法。32°F 是水的冰点——freezing point。",
