            culturalNote: "1 mile ≈ 1.6 km。快速估算：英里数 × 1.5 + 10% ≈ 公里数。2 miles ≈ 3.2 km。美国人说距离永远用 miles，说 kilometers 会被看成外星人。",
            casualVersion: "It's 2 miles. Walking would take like 40 minutes.",
