            formalityVariants: { casual: "Done by eleven thirty. Hour and a half, tops.", standard: "It should wrap up by eleven thirty at the latest.", formal: "The meeting should conclude by eleven thirty at the latest, so the total duration would be approximately one hour and thirty minutes." },
