            formalityVariants: { casual: "Good call. I'll shoot you the link at nine fifty.", standard: "Good idea. I'll send you the meeting link around nine fifty.", formal: "That is a prudent plan. I will forward the meeting link to you at approximately nine fifty, just to ensure everything is in order." },
