            alternativeExpressions: [
              { textEn: "No pressure at all! Can I at least leave you some info to look over when you have time?", textZh: "完全不勉强！我能留一些资料给你有空时看看吗？", actionHint: "look over 就是看一看", frequency: "common" },
            ],
