            formalityVariants: { casual: "Nah, I'm good. I'll Google you if I change my mind. See ya!", standard: "I appreciate the offer, but I'll pass. I'll look you up online if I change my mind.", formal: "Thank you very much for the information, but I shall have to decline at this time. Should I reconsider in the future, I will certainly look into your company's offerings online. I wish you a pleasant day." },
