            formalityVariants: { casual: "Hey, gotta move my Tuesday appointment. Something came up.", standard: "I have an appointment on Tuesday but something came up. Can I reschedule?", formal: "Good morning. I regret to inform you that an unexpected matter has arisen and I will be unable to attend my appointment with Dr. Chen on Tuesday. Would it be possible to reschedule?" },
