            formalityVariants: { casual: "Same one, medium. If you don't have it, refund's fine.", standard: "I'll take an exchange if you have a medium. Otherwise, a refund please.", formal: "I would prefer an exchange for the same jacket in size medium, if available. Should the item not be in stock, I would like to request a full refund." },
