            formalityVariants: { casual: "Yeah, twenty bucks plus tax. Wanna try it?", standard: "Exactly, $19.99 before tax. Would you like to try it on?", formal: "That is correct — $19.99 before applicable sales tax. Would you care to try it on for size?" },
