            casualVersion: "Yep, same thing. Just follow the arrow — it's down there.",
            formalityVariants: { casual: "Yeah, same thing. Just go that way.", standard: "Yep, same thing. We say 'restroom' in public and 'bathroom' at home. Follow the arrow.", formal: "Yes, they refer to the same facility. In public settings, 'restroom' is the preferred term, while 'bathroom' is more commonly used in domestic contexts. Simply follow the directional arrow to locate it." },
