            formalityVariants: { casual: "Thanks! So what's a normal tip here?", standard: "Thank you. How much should I tip? I'm still learning the tipping culture.", formal: "Thank you very much. If you don't mind my asking, what would be an appropriate gratuity? I'm visiting from abroad and am unfamiliar with the customary practice." },
